inline:
/* Disable header transparency */
.fern-theme-default.fern-container .fern-header,
.fern-theme-default.fern-container .fern-header-tabs {
    background-color: rgb(var(--background)) !important;
    border-bottom-color: var(--border) !important;
}
.fern-theme-default.fern-container .fern-header-tabs .fern-background {
    opacity: 1 !important;
}
@media (min-width: 1024px) {
    .fern-theme-default.fern-container .fern-header {
        border-bottom-width: 0 !important;
    }
}

/* Append "(latest)" to the latest version's label in the versions dropdown. */
.fern-dropdown[data-testid="version-dropdown-content"] .fern-dropdown-item:not([href^="/v"]) .items-center div:after {
    content: " (latest)";
}

/* Slightly increase the horizontal space between the logo and the version dropdown. */
/* (only in "desktop" versions because mobile lacks width) */
@media (min-width: 1024px) {
    .fern-header-content .items-center.gap-2 {
        gap: 1rem !important;
    }
}

/* Slightly reduce the logo width on mobile to make sure all header buttons remain visible */
@media (max-width: 480px) {
    .fern-logo-container {
        max-width: 130px !important;
    }
}

/* Center-align YouTube videos */
iframe[src*="//youtube.com/"], iframe[src*="//www.youtube.com/"] {
    display: block;
    margin: 0 auto;
}
/* Make YouTube videos fit the width on mobile */
@media screen and (max-width: 769px) {
    iframe[src*="//youtube.com/"], iframe[src*="//www.youtube.com/"] {
        max-width: 100% !important;
        width: auto !important;
        height: auto !important;
    }
}

/* Mark deprecated endpoints in the API Reference navigation. */
/* Endpoints are identified by their 'href', which is a hyphenated version of operationId. */
.fern-sidebar-link[href$="entities-me"] .fern-sidebar-link-text,
.fern-sidebar-link[href$="post-entities-id-documents"] .fern-sidebar-link-text,
.fern-sidebar-link[href$="put-entities-id-onboarding-data"] .fern-sidebar-link-text,
.fern-sidebar-link[href$="get-entities-id-onboarding-requirements"] .fern-sidebar-link-text,
.fern-sidebar-link[href$="post-persons-id-documents"] .fern-sidebar-link-text,
.fern-sidebar-link[href$="post-receivables-id-mark-as-partially-paid"] .fern-sidebar-link-text
 {
    text-decoration: line-through;
    color: var(--grayscale-8);
}

.th-left-aligned {
    text-align: left;
}

/* Landing page styles from ReadMe */

@media (min-width: 1280px) {
    /* Do not add left-side whitespace if TOC is disabled */
    .fern-theme-default.fern-container .fern-sidebar-disabled:has(.fern-overview-layout, .fern-guide-layout):has(.fern-layout-toc) {
        padding-left: 0 !important;
    }

    /* Remove extra left-side whitespace */
    head:has(meta[property="og:title"][content^="Welcome to Monite Doc"]) + body .fern-overview-layout {
        padding-left: 0 !important;
    }
    head:has(meta[property="og:title"][content^="Welcome to Monite Doc"]) + body .max-w-content-wide-width {
        max-width: 100% !important;
    }
}

